window.LESSON_DATA={"schemaVersion":"5.0.0","version":"5.0.0","buildDate":"2026-08-07","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":2,"title":"Functions"},"lesson":{"number":"2.1","slug":"functions-domain-range-representations","title":"Functions, Domain, Range, and Representations","subtitle":"Relations, notation, domains, ranges, graph features, TI-84 evidence, inverse relations, and contextual interpretation.","objectives":["Decide whether a relation is a function from any representation.","Use function notation in image and preimage directions.","Determine mathematical and contextual domains and ranges.","Read intercepts, extrema, intervals, discontinuities, and asymptotes.","Use TI-84 Zero, Minimum, Maximum, Intersect, and TABLE transparently.","Interpret inverse relations through coordinate exchange and reflection in y=x."],"vocab":["relation","function","domain","codomain","range","image","preimage","independent variable","dependent variable","zero","intercept","local maximum","global maximum","increasing","decreasing","asymptote","inverse relation"],"technology":"TI-84 graphing evidence follows conceptual understanding and must be recorded with model, settings, output, verification, and interpretation.","ti84_workflows":["Zero","Minimum/Maximum","Intersect","TABLE/TBLSET"],"teachingBlocks":[{"code":"2.1A","title":"Relations and Functions","estimatedClassroomTime":"60–75 minutes"},{"code":"2.1B","title":"Function Notation","estimatedClassroomTime":"60–75 minutes"},{"code":"2.1C","title":"Domain and Range","estimatedClassroomTime":"60–75 minutes"},{"code":"2.1D","title":"Graph Features","estimatedClassroomTime":"60–75 minutes"},{"code":"2.1E","title":"TI-84 Evidence","estimatedClassroomTime":"60–75 minutes"},{"code":"2.1F","title":"Inverse Relations and Synthesis","estimatedClassroomTime":"60–75 minutes"}]},"slides":[{"section":"2.1A · Relations and Functions","title":"Functions, Domain, Range, and Representations","kind":"cover","eyebrow":"IB Mathematics: Applications and Interpretation SL","html":"<div class=\"v5-cover\"><div><div class=\"v5-kicker\">UNIT 2 · FUNCTIONS</div><div class=\"v5-number\">2.1</div><h1>Functions, Domain, Range, and Representations</h1><p>Build a precise language for models: what inputs are permitted, what output is produced, which graph features matter, and how technology supplies verifiable evidence.</p><div class=\"v5-pills\"><span>Relations</span><span>Notation</span><span>Domain &amp; range</span><span>Graph features</span><span>TI‑84 evidence</span><span>Inverse relations</span></div><button class=\"primary-btn route-jump\" data-go=\"practice\">Open Practice Studio</button></div><div class=\"v5-cover-visual\"><svg viewBox=\"0 0 680 520\" role=\"img\" aria-label=\"A function model linking data, rule, graph and decision\"><defs><marker id=\"cvA\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10Z\" fill=\"#177e89\"/></marker></defs><rect x=\"15\" y=\"15\" width=\"650\" height=\"490\" rx=\"36\" fill=\"#fff\" stroke=\"#d8d0c6\"/><circle cx=\"340\" cy=\"255\" r=\"88\" fill=\"#17324d\"/><text x=\"340\" y=\"245\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"25\" font-weight=\"900\">FUNCTION</text><text x=\"340\" y=\"278\" text-anchor=\"middle\" fill=\"#d9f0ee\" font-size=\"17\">input → one output</text><g fill=\"#f7f2eb\" stroke=\"#d8d0c6\"><rect x=\"55\" y=\"65\" width=\"170\" height=\"95\" rx=\"20\"/><rect x=\"455\" y=\"65\" width=\"170\" height=\"95\" rx=\"20\"/><rect x=\"55\" y=\"365\" width=\"170\" height=\"95\" rx=\"20\"/><rect x=\"455\" y=\"365\" width=\"170\" height=\"95\" rx=\"20\"/></g><g fill=\"#7a1733\" font-weight=\"900\" font-size=\"16\" text-anchor=\"middle\"><text x=\"140\" y=\"102\">CONTEXT</text><text x=\"540\" y=\"102\">RULE</text><text x=\"140\" y=\"402\">DATA</text><text x=\"540\" y=\"402\">GRAPH</text></g><g fill=\"#52616d\" font-size=\"14\" text-anchor=\"middle\"><text x=\"140\" y=\"132\">meaning · units · limits</text><text x=\"540\" y=\"132\">f(x) with a domain</text><text x=\"140\" y=\"432\">ordered pairs · table</text><text x=\"540\" y=\"432\">features · solutions</text></g><g stroke=\"#177e89\" stroke-width=\"5\" fill=\"none\" marker-end=\"url(#cvA)\"><path d=\"M225 125C265 145 280 170 298 191\"/><path d=\"M455 125C415 145 400 170 382 191\"/><path d=\"M225 410C270 390 287 350 302 320\"/><path d=\"M455 410C410 390 393 350 378 320\"/></g></svg></div></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Launch investigation · solar canopy data audit","kind":"content","eyebrow":"One timestamp must produce one recorded output","html":"<div class=\"v5-launch\"><section><span>DATA INTEGRITY PROBLEM</span><h2>A solar canopy reports power once every hour.</h2><p>At 11:00, the exported file contains both 84 kW and 91 kW. The dashboard uses a single curve to predict output throughout the day.</p><table class=\"v5-table\"><tr><th>Time</th><th>08:00</th><th>09:00</th><th>10:00</th><th>11:00</th><th>11:00</th><th>12:00</th></tr><tr><th>Power (kW)</th><td>31</td><td>48</td><td>67</td><td>84</td><td>91</td><td>96</td></tr></table></section><section class=\"v5-launch-questions\"><h3>Before using a formula or graph:</h3><ol><li>What is the input?</li><li>What is the output?</li><li>Why does the duplicated time create a mathematical problem?</li><li>Name two possible data explanations.</li><li>What evidence is needed before deleting either record?</li></ol><textarea class=\"student-note tall\" data-note=\"v5-launch\" placeholder=\"Write an initial audit note.\"></textarea></section></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"The learning route","kind":"content","eyebrow":"Six connected ideas · one coherent model","html":"<div class=\"v5-route\"><article><b>2.1A</b><h3>Function rule</h3><p>Relations, mappings, tables, equations and graphs.</p></article><article><b>2.1B</b><h3>Notation</h3><p>Images, preimages, variables and interpretation.</p></article><article><b>2.1C</b><h3>Domain &amp; range</h3><p>Algebraic, graphical and contextual restrictions.</p></article><article><b>2.1D</b><h3>Graph evidence</h3><p>Intercepts, extrema, intervals and intersections.</p></article><article><b>2.1E</b><h3>TI‑84 workflows</h3><p>Window, table, zero, extrema and intersect.</p></article><article><b>2.1F</b><h3>Inverse relations</h3><p>Coordinate swap, reflection and interpretation.</p></article></div><div class=\"v5-note\"><b>Lesson habit:</b> name the representation, state the permitted domain, produce mathematical evidence, then interpret with units.</div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"A relation records input–output pairs","kind":"content","eyebrow":"The broad structure","html":"<div class=\"v5-three\"><article><span>ORDERED PAIRS</span><div class=\"v5-mathbox\"><span>Relation</span><div>\\[R=\\{(-2,5),(0,1),(3,5)\\}\\]</div></div></article><article><span>LANGUAGE</span><h2>Input first, output second</h2><p>The pair \\((x,y)\\) records one input and the output connected to it.</p></article><article><span>REPRESENTATIONS</span><ul><li>ordered pairs</li><li>mapping diagram</li><li>table</li><li>equation or rule</li><li>graph</li><li>verbal context</li></ul></article></div><div class=\"v5-note\"><b>Important:</b> a relation need not be a function.</div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"A function gives exactly one output for every permitted input","kind":"content","eyebrow":"Definition before procedure","html":"<div class=\"v5-two\"><article><span>ALLOWED</span><h2>Many-to-one</h2><p>Different inputs may share the same output.</p></article><article><span>NOT ALLOWED</span><h2>One-to-many</h2><p>One permitted input may not have two different outputs.</p></article></div><div class=\"v5-mathbox\"><span>Function condition</span><div>\\[x\\in D_f\\Longrightarrow \\text{exactly one value }f(x)\\]</div></div><div class=\"v5-note\"><b>The word permitted matters:</b> only inputs in the domain are tested.</div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Three mapping patterns","kind":"content","eyebrow":"Follow arrows from each input","html":"<svg class=\"v5-svg\" viewBox=\"0 0 960 360\" role=\"img\" aria-label=\"One-to-one, many-to-one and one-to-many mapping diagrams\">\n<defs><marker id=\"mA\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10Z\" fill=\"#177e89\"/></marker><marker id=\"mR\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0L10 5L0 10Z\" fill=\"#a83246\"/></marker></defs>\n<g transform=\"translate(20 20)\"><rect width=\"280\" height=\"320\" rx=\"24\" fill=\"#fff\" stroke=\"#d8d0c6\"/><text x=\"140\" y=\"42\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#1f7a4d\">ONE-TO-ONE</text><circle cx=\"72\" cy=\"112\" r=\"28\" fill=\"#edf8f7\" stroke=\"#177e89\" stroke-width=\"4\"/><circle cx=\"72\" cy=\"220\" r=\"28\" fill=\"#edf8f7\" stroke=\"#177e89\" stroke-width=\"4\"/><circle cx=\"210\" cy=\"112\" r=\"28\" fill=\"#fff7df\" stroke=\"#d4a72c\" stroke-width=\"4\"/><circle cx=\"210\" cy=\"220\" r=\"28\" fill=\"#fff7df\" stroke=\"#d4a72c\" stroke-width=\"4\"/><text x=\"72\" y=\"120\" text-anchor=\"middle\" font-weight=\"900\">1</text><text x=\"72\" y=\"228\" text-anchor=\"middle\" font-weight=\"900\">2</text><text x=\"210\" y=\"120\" text-anchor=\"middle\" font-weight=\"900\">A</text><text x=\"210\" y=\"228\" text-anchor=\"middle\" font-weight=\"900\">B</text><path d=\"M102 112H177\" stroke=\"#177e89\" stroke-width=\"5\" marker-end=\"url(#mA)\"/><path d=\"M102 220H177\" stroke=\"#177e89\" stroke-width=\"5\" marker-end=\"url(#mA)\"/><text x=\"140\" y=\"293\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#1f7a4d\">FUNCTION</text></g>\n<g transform=\"translate(340 20)\"><rect width=\"280\" height=\"320\" rx=\"24\" fill=\"#fff\" stroke=\"#d8d0c6\"/><text x=\"140\" y=\"42\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#1f7a4d\">MANY-TO-ONE</text><circle cx=\"72\" cy=\"112\" r=\"28\" fill=\"#edf8f7\" stroke=\"#177e89\" stroke-width=\"4\"/><circle cx=\"72\" cy=\"220\" r=\"28\" fill=\"#edf8f7\" stroke=\"#177e89\" stroke-width=\"4\"/><circle cx=\"210\" cy=\"166\" r=\"31\" fill=\"#fff7df\" stroke=\"#d4a72c\" stroke-width=\"4\"/><text x=\"72\" y=\"120\" text-anchor=\"middle\" font-weight=\"900\">1</text><text x=\"72\" y=\"228\" text-anchor=\"middle\" font-weight=\"900\">2</text><text x=\"210\" y=\"174\" text-anchor=\"middle\" font-weight=\"900\">A</text><path d=\"M99 120L177 151\" stroke=\"#177e89\" stroke-width=\"5\" marker-end=\"url(#mA)\"/><path d=\"M99 212L177 181\" stroke=\"#177e89\" stroke-width=\"5\" marker-end=\"url(#mA)\"/><text x=\"140\" y=\"293\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#1f7a4d\">FUNCTION</text></g>\n<g transform=\"translate(660 20)\"><rect width=\"280\" height=\"320\" rx=\"24\" fill=\"#fff\" stroke=\"#d8d0c6\"/><text x=\"140\" y=\"42\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#a83246\">ONE-TO-MANY</text><circle cx=\"72\" cy=\"166\" r=\"28\" fill=\"#fff1f3\" stroke=\"#a83246\" stroke-width=\"4\"/><circle cx=\"210\" cy=\"112\" r=\"28\" fill=\"#fff7df\" stroke=\"#d4a72c\" stroke-width=\"4\"/><circle cx=\"210\" cy=\"220\" r=\"28\" fill=\"#fff7df\" stroke=\"#d4a72c\" stroke-width=\"4\"/><text x=\"72\" y=\"174\" text-anchor=\"middle\" font-weight=\"900\">1</text><text x=\"210\" y=\"120\" text-anchor=\"middle\" font-weight=\"900\">A</text><text x=\"210\" y=\"228\" text-anchor=\"middle\" font-weight=\"900\">B</text><path d=\"M100 154L177 123\" stroke=\"#a83246\" stroke-width=\"5\" marker-end=\"url(#mR)\"/><path d=\"M100 178L177 209\" stroke=\"#a83246\" stroke-width=\"5\" marker-end=\"url(#mR)\"/><text x=\"140\" y=\"293\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#a83246\">NOT A FUNCTION</text></g></svg>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Tables and ordered pairs: inspect repeated inputs","kind":"content","eyebrow":"Repeated outputs are allowed","html":"<div class=\"v5-compare\"><section><span>FUNCTION</span><table class=\"v5-table\"><tr><th>x</th><th>−2</th><th>0</th><th>4</th></tr><tr><th>y</th><td>7</td><td>7</td><td>11</td></tr></table><p>The output 7 repeats, but every input has one output.</p></section><section class=\"bad\"><span>NOT A FUNCTION</span><table class=\"v5-table\"><tr><th>x</th><th>−2</th><th>0</th><th>0</th></tr><tr><th>y</th><td>7</td><td>7</td><td>11</td></tr></table><p>The input 0 produces two different outputs.</p></section></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Equations: solve for the output when necessary","kind":"content","eyebrow":"An equation may hide more than one output","html":"<div class=\"v5-three\"><article><span>EXPLICIT FUNCTION</span><div class=\"v5-mathbox\"><span></span><div>\\[y=2x-3\\]</div></div><p>Every real input has one real output.</p></article><article><span>IMPLICIT RELATION</span><div class=\"v5-mathbox\"><span></span><div>\\[x^2+y^2=25\\]</div></div><p>For \\(x=3\\), \\(y=4\\) or \\(y=-4\\). The full circle is not \\(y\\) as a function of \\(x\\).</p></article><article><span>RESTRICTED BRANCH</span><div class=\"v5-mathbox\"><span></span><div>\\[y=\\sqrt{25-x^2},\\ -5\\le x\\le5\\]</div></div><p>The upper semicircle chooses one output for each permitted input.</p></article></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"The vertical-line test","kind":"content","eyebrow":"A graph test for one output per input","html":"<svg class=\"v5-svg\" viewBox=\"0 0 940 360\" role=\"img\" aria-label=\"Vertical line test on a parabola and a circle\"><g transform=\"translate(20 20)\"><rect width=\"430\" height=\"320\" rx=\"24\" fill=\"#fff\" stroke=\"#d8d0c6\"/><line x1=\"48\" y1=\"255\" x2=\"390\" y2=\"255\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"215\" y1=\"290\" x2=\"215\" y2=\"42\" stroke=\"#17324d\" stroke-width=\"3\"/><path d=\"M70 250Q215 35 360 250\" fill=\"none\" stroke=\"#177e89\" stroke-width=\"7\"/><line x1=\"286\" y1=\"52\" x2=\"286\" y2=\"278\" stroke=\"#d4a72c\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/><circle cx=\"286\" cy=\"104\" r=\"8\" fill=\"#d4a72c\"/><text x=\"215\" y=\"310\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#1f7a4d\">ONE INTERSECTION · FUNCTION</text></g><g transform=\"translate(490 20)\"><rect width=\"430\" height=\"320\" rx=\"24\" fill=\"#fff\" stroke=\"#d8d0c6\"/><line x1=\"48\" y1=\"170\" x2=\"390\" y2=\"170\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"215\" y1=\"290\" x2=\"215\" y2=\"42\" stroke=\"#17324d\" stroke-width=\"3\"/><ellipse cx=\"215\" cy=\"170\" rx=\"126\" ry=\"92\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\"/><line x1=\"286\" y1=\"52\" x2=\"286\" y2=\"278\" stroke=\"#d4a72c\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/><circle cx=\"286\" cy=\"95\" r=\"8\" fill=\"#d4a72c\"/><circle cx=\"286\" cy=\"245\" r=\"8\" fill=\"#d4a72c\"/><text x=\"215\" y=\"310\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#a83246\">TWO INTERSECTIONS · NOT A FUNCTION</text></g></svg><div class=\"v5-note\"><b>Decision:</b> if any vertical line meets the relation more than once, the relation is not a function of \\(x\\).</div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Worked example · classify a mixed relation","kind":"worked","eyebrow":"Use the definition, not appearance","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>A relation contains \\((-3,8),(0,2),(4,8),(0,-1)\\). Decide whether it defines \\(y\\) as a function of \\(x\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>List the inputs: \\(-3,0,4,0\\).</li><li>The input \\(0\\) is paired with both \\(2\\) and \\(-1\\).</li><li>One permitted input therefore has two different outputs.</li></ol><div class=\"v5-answer\">\\[\\boxed{\\text{The relation is not a function of }x.}\\]</div><div class=\"v5-check\"><b>Check</b><p>The repeated output 8 is harmless; the repeated input 0 is decisive.</p></div></section></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Student turn · classify from three representations","kind":"student","eyebrow":"Commit before revealing","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>A mapping sends \\(-2\\mapsto6\\), \\(1\\mapsto4\\), \\(5\\mapsto6\\). The same data are graphed as three points. Decide whether the relation is a function, then state its domain and range.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-a-turn\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">It is a function because each input has one arrow and one plotted output. Domain \\(=\\{-2,1,5\\}\\); range \\(=\\{4,6\\}\\). Repeated output 6 is allowed.</div></details></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Misconception clinic · repeated outputs","kind":"content","eyebrow":"Read arrows from the input side","html":"<div class=\"v5-two\"><article><span>INCORRECT CLAIM</span><h2>“Two inputs point to 6, so it is not a function.”</h2></article><article><span>REPAIR</span><h2>Many-to-one is allowed.</h2><p>A function fails only when one permitted input produces two different outputs, or when a required input has no output.</p></article></div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"A function is a rule together with its domain","kind":"content","eyebrow":"Same formula · different function","html":"<div class=\"v5-two\"><article><span>FULL REAL DOMAIN</span><div class=\"v5-mathbox\"><span></span><div>\\[f(x)=x^2,\\quad x\\in\\mathbb R\\]</div></div><p>Many-to-one; inverse relation is not a function.</p></article><article><span>RESTRICTED DOMAIN</span><div class=\"v5-mathbox\"><span></span><div>\\[g(x)=x^2,\\quad x\\ge0\\]</div></div><p>One-to-one; inverse relation is a function.</p></article></div><div class=\"v5-note\"><b>Model contract:</b> rule + domain + variable meaning + units.</div>","block":"A"},{"section":"2.1A · Relations and Functions","title":"Checkpoint · function or not?","kind":"checkpoint","eyebrow":"Retrieve the defining condition","html":"<div class=\"v5-checkpoint\"><div><span>RETRIEVAL CHECK</span><h2>Explain before looking back</h2><p>Complete each item from memory, then revisit only the screen that addresses the missing idea.</p></div><ol><li>Explain why many-to-one can still be a function.</li><li>State what makes one-to-many invalid.</li><li>Use ordered pairs to identify a repeated-input conflict.</li><li>Explain the vertical-line test in terms of input and output.</li><li>Explain why changing the domain can change whether an inverse relation is a function.</li></ol><textarea class=\"student-note\" data-note=\"v5-a-check\" placeholder=\"Which idea needs another example?\"></textarea></div>","block":"A"},{"section":"2.1B · Function Notation","title":"Function notation, images, and preimages","kind":"content","eyebrow":"Two directions of reasoning","html":"<div class=\"v5-block-open\"><b>2.1B</b><h2>Move forward and backward through a function</h2><p><strong>Image:</strong> input known, output required. <strong>Preimage:</strong> output known, all permitted inputs required.</p><div class=\"v5-flow\"><span>input</span><i>apply the rule</i><span>image</span><i>solve backward</i><span>preimage(s)</span></div></div>","block":"B"},{"section":"2.1B · Function Notation","title":"The symbol f names a rule; f(x) names an output","kind":"content","eyebrow":"Notation is not multiplication","html":"<div class=\"v5-two\"><article><span>FUNCTION</span><div class=\"v5-mathbox\"><span></span><div>\\[f:x\\mapsto2x^2-3x+1\\]</div></div><p>The letter \\(f\\) names the entire input–output rule.</p></article><article><span>FUNCTION VALUE</span><div class=\"v5-mathbox\"><span></span><div>\\[f(4)=2(4)^2-3(4)+1=21\\]</div></div><p>\\(f(4)\\) is the image of the input 4.</p></article></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Worked example · evaluate a function","kind":"worked","eyebrow":"Substitute into every occurrence","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>For \\(g(t)=3t^2-5t-4\\), calculate \\(g(4)\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Replace every \\(t\\) with 4.</li><li>\\(g(4)=3(4)^2-5(4)-4\\).</li><li>\\(g(4)=48-20-4=24\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{g(4)=24}\\]</div></section></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Negative inputs require brackets","kind":"content","eyebrow":"Preserve the sign","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Calculate \\(h(-2)\\) for \\(h(x)=4x^2+3x-1\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Use brackets around the negative input.</li><li>\\(h(-2)=4(-2)^2+3(-2)-1\\).</li><li>\\(h(-2)=16-6-1=9\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{h(-2)=9}\\]</div><div class=\"v5-check\"><b>Check</b><p>Without brackets, a calculator entry can square only the 2 and lose the intended sign structure.</p></div></section></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Algebraic inputs reveal structure","kind":"content","eyebrow":"Substitute an expression, then simplify","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>For \\(f(x)=2x-5\\), find \\(f(3a+1)\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Replace \\(x\\) with the entire expression \\(3a+1\\).</li><li>\\(f(3a+1)=2(3a+1)-5\\).</li><li>Expand and collect: \\(6a+2-5=6a-3\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{f(3a+1)=6a-3}\\]</div></section></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Images and preimages","kind":"content","eyebrow":"Name the direction","html":"<div class=\"v5-three\"><article><span>IMAGE</span><div class=\"v5-mathbox\"><span></span><div>\\[f(3)=11\\]</div></div><p>11 is the image of 3.</p></article><article><span>PREIMAGE</span><div class=\"v5-mathbox\"><span></span><div>\\[f(x)=11\\]</div></div><p>Any permitted solution \\(x\\) is a preimage of 11.</p></article><article><span>MULTIPLE PREIMAGES</span><div class=\"v5-mathbox\"><span></span><div>\\[p(-4)=p(4)=16\\]</div></div><p>A function may give one output more than one preimage.</p></article></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Read an image and preimages from a graph","kind":"content","eyebrow":"Vertical for image · horizontal for preimage","html":"<div class=\"v5-graph-pair\"><section><h3>Find \\(f(2)\\)</h3><p>Start at \\(x=2\\), move vertically to the graph, then horizontally to the output axis.</p></section><section><h3>Solve \\(f(x)=5\\)</h3><p>Draw \\(y=5\\); every intersection supplies a preimage.</p></section><svg viewBox=\"0 0 780 330\" role=\"img\" aria-label=\"Graph showing one image and two preimages\"><rect width=\"780\" height=\"330\" rx=\"24\" fill=\"#fff\"/><line x1=\"55\" y1=\"270\" x2=\"730\" y2=\"270\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"170\" y1=\"305\" x2=\"170\" y2=\"35\" stroke=\"#17324d\" stroke-width=\"3\"/><path d=\"M75 250C180 210 225 70 350 90C475 110 510 270 700 155\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\"/><line x1=\"55\" y1=\"145\" x2=\"730\" y2=\"145\" stroke=\"#d4a72c\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/><line x1=\"350\" y1=\"270\" x2=\"350\" y2=\"90\" stroke=\"#177e89\" stroke-width=\"4\" stroke-dasharray=\"10 8\"/><circle cx=\"350\" cy=\"90\" r=\"9\" fill=\"#177e89\"/><circle cx=\"128\" cy=\"145\" r=\"8\" fill=\"#d4a72c\"/><circle cx=\"616\" cy=\"145\" r=\"8\" fill=\"#d4a72c\"/></svg></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Read notation from a table","kind":"content","eyebrow":"Coordinates, table entries, and notation agree","html":"<div class=\"v5-table-read\"><table class=\"v5-table\"><tr><th>x</th><th>−2</th><th>0</th><th>3</th><th>7</th></tr><tr><th>f(x)</th><td>5</td><td>−1</td><td>5</td><td>12</td></tr></table><ul><li>\\(f(0)=-1\\).</li><li>The image of 7 is 12.</li><li>The preimages of 5 are \\(-2\\) and 3.</li><li>The point \\((3,5)\\) lies on the graph.</li></ul></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Interpret a function value with units","kind":"content","eyebrow":"Input, output, and context belong in the sentence","html":"<div class=\"v5-interpret\"><div>\\[C(12)=47\\]</div><p class=\"weak\"><b>Incomplete:</b> “12 gives 47.”</p><p class=\"strong\"><b>Complete:</b> For a delivery distance of 12 km, the model predicts a charge of QAR 47.</p></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Independent and dependent variables","kind":"content","eyebrow":"The output depends on the input","html":"<div class=\"v5-two\"><article><span>INDEPENDENT VARIABLE</span><h2>Input</h2><p>Chosen, controlled, or observed. Example: elapsed time \\(t\\), in minutes.</p></article><article><span>DEPENDENT VARIABLE</span><h2>Output</h2><p>Determined by the rule. Example: temperature \\(T(t)\\), in °C.</p></article></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Worked example · determine every preimage","kind":"worked","eyebrow":"Solving an output equation","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>For \\(p(x)=x^2-5\\), determine all preimages of 11.</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Set the output equal to 11: \\(x^2-5=11\\).</li><li>Solve \\(x^2=16\\).</li><li>Both \\(x=4\\) and \\(x=-4\\) belong to the stated real domain.</li></ol><div class=\"v5-answer\">\\[\\boxed{x=-4\\text{ or }x=4}\\]</div><div class=\"v5-check\"><b>Check</b><p>A horizontal line at \\(y=11\\) would meet the parabola twice.</p></div></section></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Student turn · image, preimage, and interpretation","kind":"student","eyebrow":"Use notation and words","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>A water tank is modelled by \\(V(t)=520-28t\\) litres for \\(0\\le t\\le15\\). Calculate and interpret \\(V(7.5)\\), then determine the preimage of 240.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-b-turn\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">\\(V(7.5)=520-28(7.5)=310\\). After 7.5 minutes, the model predicts 310 litres. For the preimage, solve \\(520-28t=240\\), giving \\(t=10\\) minutes.</div></details></div>","block":"B"},{"section":"2.1B · Function Notation","title":"Checkpoint · notation in both directions","kind":"checkpoint","eyebrow":"Calculate and communicate","html":"<div class=\"v5-checkpoint\"><div><span>RETRIEVAL CHECK</span><h2>Explain before looking back</h2><p>Complete each item from memory, then revisit only the screen that addresses the missing idea.</p></div><ol><li>Explain the difference between \\(f\\) and \\(f(x)\\).</li><li>Calculate \\(h(-3)\\) for \\(h(x)=4-2x\\).</li><li>Determine every preimage of 9 under \\(q(x)=x^2\\).</li><li>Interpret \\(T(8)=26\\) when \\(T\\) is minutes and the input is kilometres.</li><li>Explain why a repeated output can create multiple preimages without breaking the function rule.</li></ol><textarea class=\"student-note\" data-note=\"v5-b-check\" placeholder=\"Which idea needs another example?\"></textarea></div>","block":"B"},{"section":"2.1C · Domain and Range","title":"Domain and range","kind":"content","eyebrow":"Inputs permitted · outputs actually produced","html":"<div class=\"v5-block-open\"><b>2.1C</b><h2>A formula is only part of the model</h2><p>The mathematical domain comes from the rule. The contextual domain may be smaller because of time, capacity, counting, safety, or the range over which data were collected.</p></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Domain, codomain, and range","kind":"content","eyebrow":"Use the terms precisely","html":"<div class=\"v5-three\"><article><span>DOMAIN</span><h2>Permitted inputs</h2><p>Every input for which the function is defined in the model.</p></article><article><span>CODOMAIN</span><h2>Declared output set</h2><p>The set in which outputs are expected to lie.</p></article><article><span>RANGE</span><h2>Outputs actually attained</h2><p>The images produced by permitted inputs.</p></article></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Read domain and range from finite data","kind":"content","eyebrow":"List each value once","html":"<div class=\"v5-two\"><table class=\"v5-table\"><tr><th>x</th><th>−2</th><th>0</th><th>3</th><th>5</th></tr><tr><th>f(x)</th><td>6</td><td>1</td><td>6</td><td>9</td></tr></table><section class=\"v5-key\"><div>\\[D=\\{-2,0,3,5\\}\\]</div><div>\\[R=\\{1,6,9\\}\\]</div><p>The repeated output 6 is listed once because a set contains distinct elements.</p></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Interval, inequality, and set-builder notation","kind":"content","eyebrow":"Equivalent ways to state a continuous domain","html":"<div class=\"v5-three\"><article><span>INEQUALITY</span><div>\\[-2\\le x\\lt 5\\]</div></article><article><span>INTERVAL</span><div>\\[[-2,5)\\]</div></article><article><span>SET-BUILDER</span><div>\\[\\{x\\in\\mathbb R\\mid -2\\le x\\lt 5\\}\\]</div></article></div><div class=\"v5-note\"><b>Endpoint convention:</b> square bracket = included; round bracket = excluded or infinite.</div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Number lines make endpoint ownership visible","kind":"content","eyebrow":"Closed means included · open means excluded","html":"<div class=\"v5-numberlines\"><section><h3>\\([-3,4]\\)</h3><svg viewBox=\"0 0 640 110\"><line x1=\"55\" y1=\"52\" x2=\"585\" y2=\"52\" stroke=\"#17324d\" stroke-width=\"4\"/><line x1=\"165\" y1=\"52\" x2=\"485\" y2=\"52\" stroke=\"#177e89\" stroke-width=\"11\"/><circle cx=\"165\" cy=\"52\" r=\"12\" fill=\"#177e89\"/><circle cx=\"485\" cy=\"52\" r=\"12\" fill=\"#177e89\"/><text x=\"165\" y=\"92\" text-anchor=\"middle\">−3</text><text x=\"485\" y=\"92\" text-anchor=\"middle\">4</text></svg></section><section><h3>\\((-3,4]\\)</h3><svg viewBox=\"0 0 640 110\"><line x1=\"55\" y1=\"52\" x2=\"585\" y2=\"52\" stroke=\"#17324d\" stroke-width=\"4\"/><line x1=\"165\" y1=\"52\" x2=\"485\" y2=\"52\" stroke=\"#7a1733\" stroke-width=\"11\"/><circle cx=\"165\" cy=\"52\" r=\"12\" fill=\"#fff\" stroke=\"#7a1733\" stroke-width=\"5\"/><circle cx=\"485\" cy=\"52\" r=\"12\" fill=\"#7a1733\"/><text x=\"165\" y=\"92\" text-anchor=\"middle\">−3</text><text x=\"485\" y=\"92\" text-anchor=\"middle\">4</text></svg></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Project a graph onto the axes","kind":"content","eyebrow":"Horizontal projection gives domain · vertical projection gives range","html":"<svg class=\"v5-svg\" viewBox=\"0 0 780 410\" role=\"img\" aria-label=\"Graph projections showing domain and range\"><rect x=\"15\" y=\"15\" width=\"750\" height=\"380\" rx=\"28\" fill=\"#fff\" stroke=\"#d8d0c6\"/><g stroke=\"#ece5dd\" stroke-width=\"1\"><line x1=\"70\" y1=\"45\" x2=\"70\" y2=\"345\"/><line x1=\"120\" y1=\"45\" x2=\"120\" y2=\"345\"/><line x1=\"170\" y1=\"45\" x2=\"170\" y2=\"345\"/><line x1=\"220\" y1=\"45\" x2=\"220\" y2=\"345\"/><line x1=\"270\" y1=\"45\" x2=\"270\" y2=\"345\"/><line x1=\"320\" y1=\"45\" x2=\"320\" y2=\"345\"/><line x1=\"370\" y1=\"45\" x2=\"370\" y2=\"345\"/><line x1=\"420\" y1=\"45\" x2=\"420\" y2=\"345\"/><line x1=\"470\" y1=\"45\" x2=\"470\" y2=\"345\"/><line x1=\"520\" y1=\"45\" x2=\"520\" y2=\"345\"/><line x1=\"570\" y1=\"45\" x2=\"570\" y2=\"345\"/><line x1=\"620\" y1=\"45\" x2=\"620\" y2=\"345\"/><line x1=\"670\" y1=\"45\" x2=\"670\" y2=\"345\"/><line x1=\"45\" y1=\"70\" x2=\"720\" y2=\"70\"/><line x1=\"45\" y1=\"115\" x2=\"720\" y2=\"115\"/><line x1=\"45\" y1=\"160\" x2=\"720\" y2=\"160\"/><line x1=\"45\" y1=\"205\" x2=\"720\" y2=\"205\"/><line x1=\"45\" y1=\"250\" x2=\"720\" y2=\"250\"/><line x1=\"45\" y1=\"295\" x2=\"720\" y2=\"295\"/><line x1=\"45\" y1=\"340\" x2=\"720\" y2=\"340\"/></g><line x1=\"45\" y1=\"295\" x2=\"720\" y2=\"295\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"270\" y1=\"355\" x2=\"270\" y2=\"38\" stroke=\"#17324d\" stroke-width=\"3\"/><path d=\"M120 270C180 215 220 95 330 110C430 124 470 275 640 170\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"120\" cy=\"270\" r=\"11\" fill=\"#fff\" stroke=\"#7a1733\" stroke-width=\"5\"/><circle cx=\"640\" cy=\"170\" r=\"11\" fill=\"#7a1733\"/><line x1=\"120\" y1=\"315\" x2=\"640\" y2=\"315\" stroke=\"#177e89\" stroke-width=\"10\" stroke-linecap=\"round\"/><circle cx=\"120\" cy=\"315\" r=\"10\" fill=\"#fff\" stroke=\"#177e89\" stroke-width=\"5\"/><circle cx=\"640\" cy=\"315\" r=\"10\" fill=\"#177e89\"/><line x1=\"690\" y1=\"110\" x2=\"690\" y2=\"270\" stroke=\"#d4a72c\" stroke-width=\"10\" stroke-linecap=\"round\"/><circle cx=\"690\" cy=\"110\" r=\"10\" fill=\"#d4a72c\"/><circle cx=\"690\" cy=\"270\" r=\"10\" fill=\"#fff\" stroke=\"#d4a72c\" stroke-width=\"5\"/><text x=\"380\" y=\"344\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#177e89\">DOMAIN PROJECTION</text><text x=\"710\" y=\"195\" transform=\"rotate(-90 710 195)\" text-anchor=\"middle\" font-weight=\"900\" fill=\"#9a7317\">RANGE PROJECTION</text></svg>","block":"C"},{"section":"2.1C · Domain and Range","title":"Natural domain: denominators cannot be zero","kind":"content","eyebrow":"Factor first when needed","html":"<div class=\"v5-three\"><article><span>RULE</span><div class=\"v5-mathbox\"><span></span><div>\\[r(x)=\\frac{7}{(x-3)(x+2)}\\]</div></div></article><article><span>EXCLUDED INPUTS</span><div class=\"v5-mathbox\"><span></span><div>\\[x\\ne3,\\quad x\\ne-2\\]</div></div></article><article><span>DOMAIN</span><div class=\"v5-mathbox\"><span></span><div>\\[(-\\infty,-2)\\cup(-2,3)\\cup(3,\\infty)\\]</div></div></article></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Natural domain: even roots require a non-negative radicand","kind":"content","eyebrow":"Solve the restriction inequality","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Determine the domain of \\(s(x)=\\sqrt{12-3x}\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Require the radicand to be non-negative: \\(12-3x\\ge0\\).</li><li>Solve: \\(-3x\\ge-12\\), so the inequality reverses when dividing by \\(-3\\).</li><li>Therefore \\(x\\le4\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{D=(-\\infty,4]}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Natural domain: logarithm inputs must be positive","kind":"content","eyebrow":"Zero is not allowed","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Determine the domain of \\(L(x)=\\log(2x-6)\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Require the logarithm argument to be positive: \\(2x-6\\gt 0\\).</li><li>Solve \\(2x\\gt 6\\).</li><li>Therefore \\(x\\gt 3\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{D=(3,\\infty)}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Combined restrictions: intersect every condition","kind":"content","eyebrow":"One rule may impose several exclusions","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Determine the domain of \\(f(x)=\\dfrac{\\sqrt{x+4}}{x^2-9}\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Square-root condition: \\(x+4\\ge0\\), so \\(x\\ge-4\\).</li><li>Denominator condition: \\(x^2-9\\ne0\\), so \\(x\\ne-3,3\\).</li><li>Intersect the conditions.</li></ol><div class=\"v5-answer\">\\[\\boxed{[-4,-3)\\cup(-3,3)\\cup(3,\\infty)}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Contextual domain can be narrower than the mathematical domain","kind":"content","eyebrow":"Time, capacity, and validation matter","html":"<div class=\"v5-three\"><article><span>FORMULA</span><div>\\[H(t)=1.5+3.2t\\]</div><p>Algebraically defined for every real \\(t\\).</p></article><article><span>EXPERIMENT</span><div>\\[0\\le t\\le6\\]</div><p>The lift journey lasts only six seconds.</p></article><article><span>RANGE</span><div>\\[1.5\\le H\\le20.7\\]</div><p>Because the function increases on the contextual domain.</p></article></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Discrete domains use whole numbers","kind":"content","eyebrow":"Counts are not continuous intervals","html":"<div class=\"v5-two\"><article><span>CONTINUOUS</span><h2>Elapsed time</h2><div>\\[0\\le t\\le12\\]</div><p>All real values in the interval are meaningful.</p></article><article><span>DISCRETE</span><h2>Completed trips</h2><div>\\[n\\in\\{0,1,2,\\ldots,40\\}\\]</div><p>Only whole-number inputs are permitted.</p></article></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Range of a monotonic function on a closed interval","kind":"content","eyebrow":"Endpoint outputs determine the bounds","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Find the range of \\(f(x)=-3x+10\\) for \\(0\\le x\\le4\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>The linear function decreases because its gradient is negative.</li><li>Evaluate the endpoints: \\(f(0)=10\\), \\(f(4)=-2\\).</li><li>Both endpoints are included.</li></ol><div class=\"v5-answer\">\\[\\boxed{R=[-2,10]}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Turning points can control the range","kind":"content","eyebrow":"Check interior extrema as well as endpoints","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>Find the range of \\(y=(x-2)^2-3\\) for \\(-1\\le x\\le5\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>The vertex \\((2,-3)\\) gives the minimum.</li><li>Endpoint values are \\(f(-1)=6\\) and \\(f(5)=6\\).</li><li>The interval is closed, so both bounds are attained.</li></ol><div class=\"v5-answer\">\\[\\boxed{R=[-3,6]}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Holes and asymptotes can remove outputs","kind":"content","eyebrow":"Approached does not mean attained","html":"<div class=\"v5-three\"><article><span>HOLE</span><p>An open point removes one coordinate unless another point has the same output.</p></article><article><span>HORIZONTAL ASYMPTOTE</span><div>\\[y=4\\]</div><p>For \\(g(x)=\\dfrac1{x-2}+4\\), the output 4 is never reached.</p></article><article><span>RANGE</span><div>\\[(-\\infty,4)\\cup(4,\\infty)\\]</div></article></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Worked example · contextual domain and range","kind":"worked","eyebrow":"State variables and units","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>A lift height is \\(h(t)=1.5+3.2t\\) metres for a journey lasting 6 seconds. State the contextual domain and range.</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Time begins at \\(t=0\\) and ends at \\(t=6\\): \\(D=[0,6]\\).</li><li>The function increases, so evaluate both endpoints.</li><li>\\(h(0)=1.5\\), \\(h(6)=20.7\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{D=[0,6]\\text{ s},\\qquad R=[1.5,20.7]\\text{ m}}\\]</div></section></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Student turn · discrete model restrictions","kind":"student","eyebrow":"Do not invent continuous inputs","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>A theatre model \\(R(n)=85n\\) gives revenue in QAR from \\(n\\) occupied seats. The theatre has 480 seats. State a contextual domain and range.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-c-turn\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">\\(n\\in\\{0,1,2,\\ldots,480\\}\\). The corresponding revenue range is \\(\\{0,85,170,\\ldots,40800\\}\\) QAR. Both sets are discrete.</div></details></div>","block":"C"},{"section":"2.1C · Domain and Range","title":"Checkpoint · restrictions and output sets","kind":"checkpoint","eyebrow":"Choose the shortest valid method","html":"<div class=\"v5-checkpoint\"><div><span>RETRIEVAL CHECK</span><h2>Explain before looking back</h2><p>Complete each item from memory, then revisit only the screen that addresses the missing idea.</p></div><ol><li>State the domain of \\(1/(x-5)\\).</li><li>State the domain of \\(\\sqrt{2x+8}\\).</li><li>Explain why \\([0,480]\\) is incomplete for a seat-count domain.</li><li>Find the range of \\(3x+2\\) on \\([-1,4)\\).</li><li>Explain how a hole or asymptote can remove a value from the range.</li></ol><textarea class=\"student-note\" data-note=\"v5-c-check\" placeholder=\"Which idea needs another example?\"></textarea></div>","block":"C"},{"section":"2.1D · Graph Features","title":"Reading and solving from graphs","kind":"content","eyebrow":"A graph is compressed mathematical evidence","html":"<div class=\"v5-block-open\"><b>2.1D</b><h2>Read the axes, domain, and features before calculating</h2><p>A trustworthy graph can reveal zeros, extrema, sign, direction of change, endpoints, gaps, asymptotes, and multiple solutions at once.</p></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Zeros and intercepts","kind":"content","eyebrow":"Value versus coordinate","html":"<div class=\"v5-three\"><article><span>ZERO / ROOT</span><div>\\[f(a)=0\\]</div><p>The input value is \\(x=a\\).</p></article><article><span>X-INTERCEPT</span><div>\\[(a,0)\\]</div><p>The coordinate where the graph crosses or touches the x-axis.</p></article><article><span>Y-INTERCEPT</span><div>\\[(0,f(0))\\]</div><p>Valid only if 0 belongs to the domain.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Local and global extrema","kind":"content","eyebrow":"Endpoints can be global extrema","html":"<div class=\"v5-four\"><article><span>LOCAL MAXIMUM</span><p>Greater than nearby outputs.</p></article><article><span>GLOBAL MAXIMUM</span><p>Greatest output on the entire stated domain.</p></article><article><span>LOCAL MINIMUM</span><p>Less than nearby outputs.</p></article><article><span>GLOBAL MINIMUM</span><p>Least output on the entire stated domain.</p></article></div><div class=\"v5-note\"><b>Report clearly:</b> the turning point \\((a,b)\\), the input where it occurs, and the extreme value, with units.</div>","block":"D"},{"section":"2.1D · Graph Features","title":"Increasing, decreasing, and constant intervals","kind":"content","eyebrow":"Move from left to right","html":"<div class=\"v5-three\"><article><span>INCREASING</span><p>As \\(x\\) increases, \\(f(x)\\) increases.</p></article><article><span>DECREASING</span><p>As \\(x\\) increases, \\(f(x)\\) decreases.</p></article><article><span>CONSTANT</span><p>The output remains unchanged over an interval.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Positive and negative intervals","kind":"content","eyebrow":"Position relative to the x-axis","html":"<div class=\"v5-two\"><article><span>POSITIVE</span><div>\\[f(x)\\gt 0\\]</div><p>The graph lies above the x-axis.</p></article><article><span>NEGATIVE</span><div>\\[f(x)\\lt 0\\]</div><p>The graph lies below the x-axis.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Misconception clinic · positive is not increasing","kind":"content","eyebrow":"Sign and direction answer different questions","html":"<div class=\"v5-two\"><article><span>INCORRECT</span><h2>“The graph is above the x-axis, so it is increasing.”</h2></article><article><span>REPAIR</span><h2>A positive graph may decrease.</h2><p>Positive/negative describes output sign. Increasing/decreasing describes how the output changes as the input moves right.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Endpoints, holes, and jumps","kind":"content","eyebrow":"Boundary ownership changes conclusions","html":"<div class=\"v5-four\"><article><span class=\"v5-dot closed\"></span><h3>Closed point</h3><p>The coordinate is included.</p></article><article><span class=\"v5-dot open\"></span><h3>Open point</h3><p>The coordinate is excluded.</p></article><article><span class=\"v5-jump\">↕</span><h3>Jump</h3><p>Two pieces approach different outputs.</p></article><article><span class=\"v5-hole\">○</span><h3>Hole</h3><p>A single point is missing.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Asymptotes describe unbounded or long-run behaviour","kind":"content","eyebrow":"A line can guide the graph without being reached","html":"<div class=\"v5-three\"><article><span>VERTICAL</span><div>\\[x=a\\]</div><p>Outputs grow without bound as inputs approach an excluded value.</p></article><article><span>HORIZONTAL</span><div>\\[y=b\\]</div><p>Outputs approach a limiting level as \\(|x|\\) becomes large.</p></article><article><span>CONTEXT</span><p>Ask whether the model remains meaningful near the asymptote or for very large inputs.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"A complete feature reading","kind":"content","eyebrow":"One graph · many conclusions","html":"<svg class=\"v5-svg\" viewBox=\"0 0 920 430\" role=\"img\" aria-label=\"Function graph with labelled intercepts, extrema, endpoint, hole and asymptote\"><rect x=\"15\" y=\"15\" width=\"890\" height=\"400\" rx=\"28\" fill=\"#fff\" stroke=\"#d8d0c6\"/><g stroke=\"#ede7df\" stroke-width=\"1\"><line x1=\"70\" y1=\"45\" x2=\"70\" y2=\"370\"/><line x1=\"130\" y1=\"45\" x2=\"130\" y2=\"370\"/><line x1=\"190\" y1=\"45\" x2=\"190\" y2=\"370\"/><line x1=\"250\" y1=\"45\" x2=\"250\" y2=\"370\"/><line x1=\"310\" y1=\"45\" x2=\"310\" y2=\"370\"/><line x1=\"370\" y1=\"45\" x2=\"370\" y2=\"370\"/><line x1=\"430\" y1=\"45\" x2=\"430\" y2=\"370\"/><line x1=\"490\" y1=\"45\" x2=\"490\" y2=\"370\"/><line x1=\"550\" y1=\"45\" x2=\"550\" y2=\"370\"/><line x1=\"610\" y1=\"45\" x2=\"610\" y2=\"370\"/><line x1=\"670\" y1=\"45\" x2=\"670\" y2=\"370\"/><line x1=\"730\" y1=\"45\" x2=\"730\" y2=\"370\"/><line x1=\"790\" y1=\"45\" x2=\"790\" y2=\"370\"/><line x1=\"850\" y1=\"45\" x2=\"850\" y2=\"370\"/><line x1=\"45\" y1=\"65\" x2=\"875\" y2=\"65\"/><line x1=\"45\" y1=\"115\" x2=\"875\" y2=\"115\"/><line x1=\"45\" y1=\"165\" x2=\"875\" y2=\"165\"/><line x1=\"45\" y1=\"215\" x2=\"875\" y2=\"215\"/><line x1=\"45\" y1=\"265\" x2=\"875\" y2=\"265\"/><line x1=\"45\" y1=\"315\" x2=\"875\" y2=\"315\"/><line x1=\"45\" y1=\"365\" x2=\"875\" y2=\"365\"/></g><line x1=\"45\" y1=\"300\" x2=\"875\" y2=\"300\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"330\" y1=\"380\" x2=\"330\" y2=\"38\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"690\" y1=\"42\" x2=\"690\" y2=\"372\" stroke=\"#d4a72c\" stroke-width=\"4\" stroke-dasharray=\"12 9\"/><path d=\"M85 320C155 275 205 110 315 125C420 140 435 335 565 335C620 335 650 270 682 175\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\" stroke-linecap=\"round\"/><path d=\"M700 95C730 155 770 230 850 260\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\" stroke-linecap=\"round\"/><circle cx=\"85\" cy=\"320\" r=\"11\" fill=\"#fff\" stroke=\"#7a1733\" stroke-width=\"5\"/><circle cx=\"850\" cy=\"260\" r=\"11\" fill=\"#7a1733\"/><circle cx=\"315\" cy=\"125\" r=\"9\" fill=\"#177e89\"/><circle cx=\"565\" cy=\"335\" r=\"9\" fill=\"#177e89\"/><circle cx=\"470\" cy=\"300\" r=\"8\" fill=\"#d4a72c\"/><circle cx=\"745\" cy=\"180\" r=\"10\" fill=\"#fff\" stroke=\"#7a1733\" stroke-width=\"5\"/><text x=\"280\" y=\"94\" font-weight=\"900\" fill=\"#177e89\">local maximum</text><text x=\"535\" y=\"365\" font-weight=\"900\" fill=\"#177e89\">local minimum</text><text x=\"440\" y=\"288\" font-weight=\"900\" fill=\"#9a7317\">zero</text><text x=\"705\" y=\"60\" font-weight=\"900\" fill=\"#9a7317\">vertical asymptote</text><text x=\"750\" y=\"165\" font-weight=\"900\" fill=\"#7a1733\">hole</text></svg><div class=\"v5-feature-list\"><span>open endpoint</span><span>zero</span><span>local maximum</span><span>local minimum</span><span>hole</span><span>vertical asymptote</span><span>closed endpoint</span></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Solve f(x)=k with a horizontal line","kind":"content","eyebrow":"Every valid intersection is a solution","html":"<div class=\"v5-three\"><article><span>SETUP</span><div>\\[y=f(x),\\qquad y=k\\]</div></article><article><span>EVIDENCE</span><p>Each intersection gives a preimage of \\(k\\).</p></article><article><span>CHECK</span><p>Report every solution in the requested domain and with justified precision.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Solve f(x)=g(x) by intersection","kind":"content","eyebrow":"Two outputs are equal at the same input","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>The functions are \\(f(x)=x^2-4x+1\\) and \\(g(x)=2x-3\\). Find their intersections.</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Set the outputs equal: \\(x^2-4x+1=2x-3\\).</li><li>Rearrange: \\(x^2-6x+4=0\\).</li><li>\\(x=3\\pm\\sqrt5\\). Substitute into \\(y=2x-3\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{(3-\\sqrt5,\\ 3-2\\sqrt5),\\quad(3+\\sqrt5,\\ 3+2\\sqrt5)}\\]</div></section></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Context can reject a mathematical intersection","kind":"content","eyebrow":"Admissibility is a mathematical step","html":"<div class=\"v5-three\"><article><span>MATHEMATICAL OUTPUT</span><p>The calculator returns \\(x=-1.7\\) and \\(x=6.2\\).</p></article><article><span>CONTEXTUAL DOMAIN</span><div>\\[0\\le x\\le10\\]</div></article><article><span>VALID CONCLUSION</span><p>Only \\(x=6.2\\) is admissible. A negative time or distance is rejected.</p></article></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Worked example · interpret a full graph","kind":"worked","eyebrow":"Coordinate, interval, and context evidence","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>A model has domain \\([-4,6]\\), zeros at \\(-2\\) and 5, a global maximum \\((1,8)\\), and a global minimum \\((6,-3)\\). State the range and explain what additional evidence is needed to determine where the function is positive.</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>The global output bounds give \\(R=[-3,8]\\).</li><li>The zeros split the domain into candidate sign intervals.</li><li>Zeros alone do not reveal whether the graph is above or below the axis on each interval; inspect the graph or test a value.</li></ol><div class=\"v5-answer\">\\[\\boxed{R=[-3,8]}\\]</div><div class=\"v5-check\"><b>Check</b><p>Sign intervals require more evidence than the locations of the zeros alone.</p></div></section></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Student turn · extract a feature set","kind":"student","eyebrow":"Use interval notation","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>From the labelled feature graph, identify the open and closed domain endpoints, the number of zeros, one local maximum, one local minimum, the hole, and the vertical asymptote. Then state one increasing interval.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-d-turn\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">The left endpoint is open and the right endpoint closed. There is one displayed zero, one local maximum, one local minimum, a hole on the right branch, and a vertical asymptote at the dashed line. The increasing interval runs from the left endpoint to the local maximum; exact endpoints depend on the labelled x-scale.</div></details></div>","block":"D"},{"section":"2.1D · Graph Features","title":"Checkpoint · graph language","kind":"checkpoint","eyebrow":"Read, solve, interpret","html":"<div class=\"v5-checkpoint\"><div><span>RETRIEVAL CHECK</span><h2>Explain before looking back</h2><p>Complete each item from memory, then revisit only the screen that addresses the missing idea.</p></div><ol><li>Distinguish a zero from an x-intercept.</li><li>Distinguish positive from increasing.</li><li>Explain how an open endpoint affects domain and range.</li><li>State what an intersection of \\(f\\) and \\(g\\) means.</li><li>Explain why the contextual domain may reject a calculator solution.</li><li>Describe the difference between a hole and a vertical asymptote.</li></ol><textarea class=\"student-note\" data-note=\"v5-d-check\" placeholder=\"Which idea needs another example?\"></textarea></div>","block":"D"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 graphing evidence","kind":"content","eyebrow":"Concept first · technology second","html":"<div class=\"v5-block-open\"><b>2.1E</b><h2>A calculator output is not yet an IB response</h2><p>Define the model and domain, enter the functions, choose a revealing window, obtain the result, verify it, and interpret it with units.</p><button class=\"v5-ti84-open\" type=\"button\" data-open-ti84>Open TI‑84 Practice Lab</button></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"Choose the window from the problem","kind":"content","eyebrow":"The window is part of the mathematical setup","html":"<div class=\"v5-three\"><article><span>XMIN / XMAX</span><p>Cover the contextual domain, not an arbitrary default window.</p></article><article><span>YMIN / YMAX</span><p>Include the relevant outputs, thresholds, and intersections.</p></article><article><span>XSCL / YSCL</span><p>Choose tick spacing that supports reading without crowding.</p></article></div><div class=\"v5-note\"><b>Warning:</b> “No intersection” in a poor window does not prove no solution.</div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"Enter functions in Y=","kind":"content","eyebrow":"Match brackets and variable structure","html":"<div class=\"v5-ti-slide\"><div class=\"v5-ti-screen\"><div>Y1=−.5(X−6)²+24</div><div>Y2=20</div><div class=\"cursor\">▮</div></div><div class=\"v5-ti-steps\"><kbd>Y=</kbd><i>→</i><span>enter \\(Y_1\\)</span><i>→</i><span>enter comparison as \\(Y_2\\)</span><i>→</i><kbd>GRAPH</kbd></div><ul><li>Use parentheses around translated inputs.</li><li>Clear or turn off old functions.</li><li>Check that each equals sign is active.</li></ul></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"Graph, Table, Trace, and CALC answer different questions","kind":"content","eyebrow":"Choose the efficient tool","html":"<div class=\"v5-four\"><article><span>GRAPH</span><p>Shape, features, number of solutions, and model comparison.</p></article><article><span>TABLE</span><p>Exact sampled values, discrete inputs, and threshold confirmation.</p></article><article><span>TRACE</span><p>Approximate coordinates and inspect nearby values.</p></article><article><span>2nd TRACE (CALC)</span><p>Zero, Minimum, Maximum, Intersect, and other numerical features.</p></article></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 Zero workflow","kind":"content","eyebrow":"Root inside a stated domain","html":"<div class=\"v5-ti-workflow\"><section><h3>Question</h3><p>Find the positive zero of \\(Y_1=x^3-4x-1\\).</p><div class=\"v5-ti-steps\"><kbd>Y=</kbd><i>→</i><kbd>GRAPH</kbd><i>→</i><kbd>2nd</kbd><kbd>TRACE</kbd><i>→</i><b>2:zero</b><i>→</i><span>left bound</span><i>→</i><span>right bound</span><i>→</i><span>guess</span></div></section><section class=\"v5-ti-screen graph\"><svg viewBox=\"0 0 360 220\"><rect width=\"360\" height=\"220\" fill=\"#d7e5c9\"/><line x1=\"25\" y1=\"110\" x2=\"335\" y2=\"110\" stroke=\"#253326\"/><line x1=\"180\" y1=\"20\" x2=\"180\" y2=\"200\" stroke=\"#253326\"/><path d=\"M42 190C95 155 120 145 153 125C190 102 205 105 230 95C265 78 286 42 320 20\" fill=\"none\" stroke=\"#1c2b1d\" stroke-width=\"4\"/><circle cx=\"245\" cy=\"110\" r=\"5\" fill=\"#1c2b1d\"/><text x=\"34\" y=\"20\" font-family=\"monospace\" font-size=\"13\">Zero X≈2.115</text></svg></section></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 Minimum and Maximum","kind":"content","eyebrow":"Report the point and the requested value","html":"<div class=\"v5-three\"><article><span>MINIMUM</span><div class=\"v5-ti-steps\"><kbd>2nd</kbd><kbd>TRACE</kbd><i>→</i><b>3:minimum</b></div><p>Set left bound, right bound, and guess around the valley.</p></article><article><span>MAXIMUM</span><div class=\"v5-ti-steps\"><kbd>2nd</kbd><kbd>TRACE</kbd><i>→</i><b>4:maximum</b></div><p>Set bounds around the peak.</p></article><article><span>IB REPORT</span><p>“The maximum output is 24 kW at \\(t=6\\) hours,” not merely “(6,24)”.</p></article></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 Intersect workflow","kind":"content","eyebrow":"Run the command near every crossing","html":"<div class=\"v5-ti-workflow\"><section><h3>Question</h3><p>Solve \\(x^2-4x+1=2x-3\\).</p><div class=\"v5-ti-steps\"><kbd>Y=</kbd><i>→</i><span>Y1 and Y2</span><i>→</i><kbd>GRAPH</kbd><i>→</i><kbd>2nd</kbd><kbd>TRACE</kbd><i>→</i><b>5:intersect</b></div><p>Move the cursor near the first crossing, press ENTER three times, then repeat near the second crossing.</p></section><section class=\"v5-ti-screen graph\"><svg viewBox=\"0 0 360 220\"><rect width=\"360\" height=\"220\" fill=\"#d7e5c9\"/><line x1=\"25\" y1=\"185\" x2=\"335\" y2=\"185\" stroke=\"#253326\"/><line x1=\"80\" y1=\"20\" x2=\"80\" y2=\"205\" stroke=\"#253326\"/><path d=\"M35 35Q180 210 325 35\" fill=\"none\" stroke=\"#1c2b1d\" stroke-width=\"4\"/><path d=\"M40 190L320 35\" fill=\"none\" stroke=\"#1c2b1d\" stroke-width=\"3\" stroke-dasharray=\"7 5\"/><circle cx=\"116\" cy=\"148\" r=\"5\"/><circle cx=\"276\" cy=\"60\" r=\"5\"/></svg></section></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TABLE and TBLSET for discrete evidence","kind":"content","eyebrow":"Set the start and increment deliberately","html":"<div class=\"v5-ti-slide\"><div class=\"v5-ti-screen table\"><table><tr><th>X</th><th>Y1</th><th>Y2</th></tr><tr><td>8</td><td>37.6</td><td>40</td></tr><tr><td>9</td><td>41.1</td><td>40</td></tr><tr><td>10</td><td>44.8</td><td>40</td></tr></table></div><div><div class=\"v5-ti-steps\"><kbd>2nd</kbd><kbd>WINDOW</kbd><i>→</i><span>TblStart</span><i>→</i><span>ΔTbl</span><i>→</i><kbd>2nd</kbd><kbd>GRAPH</kbd></div><p>For whole-number periods, set \\(\\Delta\\text{Tbl}=1\\). Compare the last failing input with the first successful input.</p></div></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"First whole-number threshold","kind":"content","eyebrow":"The adjacent value proves “first”","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>A sequence model is \\(A(n)=18(1.12)^n\\). Find the first whole number \\(n\\) for which \\(A(n)\\gt 50\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>Graph \\(Y_1=18(1.12)^X\\) and \\(Y_2=50\\), or use TABLE with \\(\\Delta\\\\text{Tbl}=1\\).</li><li>The continuous intersection is about \\(n=9.02\\), so test whole numbers 9 and 10.</li><li>\\(A(9)\\approx49.92\\lt 50\\), while \\(A(10)\\approx55.91\\gt 50\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{n=10}\\]</div><div class=\"v5-check\"><b>Check</b><p>The adjacent values establish that 10 is the first permitted integer.</p></div></section></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"A graph can hide a discontinuity or asymptote","kind":"content","eyebrow":"Pixels may connect points that mathematics excludes","html":"<div class=\"v5-three\"><article><span>ALGEBRA</span><div>\\[f(x)=\\frac{x^2-1}{x-1}\\]</div><p>The simplified expression is \\(x+1\\), but \\(x=1\\) remains excluded.</p></article><article><span>SCREEN RISK</span><p>A standard window may draw an apparently complete line and hide the single missing point.</p></article><article><span>CHECK</span><p>Use the original rule, domain analysis, and a table near \\(x=1\\).</p></article></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 practice station · Zero","kind":"student","eyebrow":"Use bounds and verify","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>Use the TI‑84 workflow to find all zeros of \\(f(x)=x^3-5x^2+2x+8\\). Record the window, each zero, and an independent check by substitution or factorization.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-ti-zero\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">The zeros are \\(x=-1,2,4\\). A suitable graph window shows three crossings. Substitution gives zero for each input, and \\(f(x)=(x+1)(x-2)(x-4)\\).</div></details></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 practice station · Maximum","kind":"student","eyebrow":"Distinguish coordinate and value","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>The power model is \\(P(t)=-0.5(t-6)^2+24\\) for \\(0\\le t\\le12\\). Use Maximum and write a complete contextual conclusion.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-ti-max\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">The calculator gives approximately \\((6,24)\\). The maximum predicted power is 24 kW, occurring 6 hours after 06:00, which is 12:00.</div></details></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 practice station · Intersect","kind":"student","eyebrow":"Find every crossing in the domain","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>Graph \\(C_1(x)=18+2.4x\\) and \\(C_2(x)=42+1.2x\\) for \\(0\\le x\\le30\\). Use Intersect and explain which plan is cheaper before and after the crossing.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-ti-int\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">The intersection occurs at \\(x=20\\), with both costs QAR 66. For \\(0\\le x\\lt 20\\), \\(C_1\\lt C_2\\). For \\(20\\lt x\\le30\\), \\(C_2\\lt C_1\\).</div></details></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"TI‑84 practice station · TABLE","kind":"student","eyebrow":"Use integer inputs","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>A maintenance cost is \\(M(n)=1200(1.08)^n\\). Use TABLE to find the first whole year for which \\(M(n)\\gt 2000\\), and show the two adjacent table values.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-ti-table\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">\\(M(6)\\approx1904.25\\lt 2000\\), while \\(M(7)\\approx2056.59\\gt 2000\\). Therefore the first whole year is \\(n=7\\).</div></details></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"Write calculator evidence as mathematics","kind":"content","eyebrow":"A complete IB response has five parts","html":"<div class=\"v5-five\"><article><span>1 · MODEL</span><p>State the equations and contextual domain.</p></article><article><span>2 · SETTINGS</span><p>Record relevant window, table start, or increment.</p></article><article><span>3 · COMMAND</span><p>Zero, Maximum, Intersect, or Table.</p></article><article><span>4 · OUTPUT</span><p>State the numerical result with justified precision.</p></article><article><span>5 · INTERPRETATION</span><p>Use variables, units, and admissibility.</p></article></div>","block":"E"},{"section":"2.1E · TI‑84 Evidence","title":"Checkpoint · choose and justify a workflow","kind":"checkpoint","eyebrow":"Technology is part of the evidence","html":"<div class=\"v5-checkpoint\"><div><span>RETRIEVAL CHECK</span><h2>Explain before looking back</h2><p>Complete each item from memory, then revisit only the screen that addresses the missing idea.</p></div><ol><li>When is TABLE better than Intersect?</li><li>Why must Zero use a left bound and right bound?</li><li>What is the difference between a maximum point and a maximum value?</li><li>Why may Intersect need to be run more than once?</li><li>How can an algebraic domain restriction expose a misleading graph?</li><li>Write a complete sentence reporting one calculator output with units.</li></ol><textarea class=\"student-note\" data-note=\"v5-e-check\" placeholder=\"Which idea needs another example?\"></textarea></div>","block":"E"},{"section":"2.1F · Inverse Relations","title":"Inverse relations and synthesis","kind":"content","eyebrow":"Reverse the correspondence","html":"<div class=\"v5-block-open\"><b>2.1F</b><h2>Exchange input and output, then ask whether the reverse is still a function</h2><p>Inverse relations reflect in \\(y=x\\), swap domain and range, and reverse contextual questions.</p></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"An inverse relation swaps coordinates","kind":"content","eyebrow":"Reverse every ordered pair","html":"<div class=\"v5-three\"><article><span>ORIGINAL</span><div>\\[(2,7),\\ (5,11),\\ (8,15)\\]</div></article><article><span>INVERSE RELATION</span><div>\\[(7,2),\\ (11,5),\\ (15,8)\\]</div></article><article><span>RULE</span><div>\\[(x,y)\\longmapsto(y,x)\\]</div></article></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Graphs reflect in y=x","kind":"content","eyebrow":"Coordinates trade places","html":"<svg class=\"v5-svg\" viewBox=\"0 0 760 430\" role=\"img\" aria-label=\"Function and inverse relation reflected in y equals x\"><rect x=\"15\" y=\"15\" width=\"730\" height=\"400\" rx=\"28\" fill=\"#fff\" stroke=\"#d8d0c6\"/><g stroke=\"#ece6de\" stroke-width=\"1\"><line x1=\"70\" y1=\"45\" x2=\"70\" y2=\"370\"/><line x1=\"125\" y1=\"45\" x2=\"125\" y2=\"370\"/><line x1=\"180\" y1=\"45\" x2=\"180\" y2=\"370\"/><line x1=\"235\" y1=\"45\" x2=\"235\" y2=\"370\"/><line x1=\"290\" y1=\"45\" x2=\"290\" y2=\"370\"/><line x1=\"345\" y1=\"45\" x2=\"345\" y2=\"370\"/><line x1=\"400\" y1=\"45\" x2=\"400\" y2=\"370\"/><line x1=\"455\" y1=\"45\" x2=\"455\" y2=\"370\"/><line x1=\"510\" y1=\"45\" x2=\"510\" y2=\"370\"/><line x1=\"565\" y1=\"45\" x2=\"565\" y2=\"370\"/><line x1=\"620\" y1=\"45\" x2=\"620\" y2=\"370\"/><line x1=\"675\" y1=\"45\" x2=\"675\" y2=\"370\"/><line x1=\"45\" y1=\"65\" x2=\"710\" y2=\"65\"/><line x1=\"45\" y1=\"115\" x2=\"710\" y2=\"115\"/><line x1=\"45\" y1=\"165\" x2=\"710\" y2=\"165\"/><line x1=\"45\" y1=\"215\" x2=\"710\" y2=\"215\"/><line x1=\"45\" y1=\"265\" x2=\"710\" y2=\"265\"/><line x1=\"45\" y1=\"315\" x2=\"710\" y2=\"315\"/><line x1=\"45\" y1=\"365\" x2=\"710\" y2=\"365\"/></g><line x1=\"45\" y1=\"350\" x2=\"710\" y2=\"350\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"95\" y1=\"390\" x2=\"95\" y2=\"35\" stroke=\"#17324d\" stroke-width=\"3\"/><line x1=\"95\" y1=\"350\" x2=\"660\" y2=\"70\" stroke=\"#d4a72c\" stroke-width=\"4\" stroke-dasharray=\"12 9\"/><path d=\"M120 332C220 305 285 245 360 170C440 90 535 78 650 66\" fill=\"none\" stroke=\"#7a1733\" stroke-width=\"7\"/><path d=\"M130 340C210 315 285 278 350 225C430 160 520 104 650 72\" fill=\"none\" stroke=\"#177e89\" stroke-width=\"7\"/><circle cx=\"300\" cy=\"225\" r=\"9\" fill=\"#7a1733\"/><circle cx=\"355\" cy=\"252\" r=\"9\" fill=\"#177e89\"/><text x=\"230\" y=\"175\" fill=\"#7a1733\" font-weight=\"900\">f</text><text x=\"500\" y=\"220\" fill=\"#177e89\" font-weight=\"900\">inverse relation</text><text x=\"570\" y=\"103\" fill=\"#9a7317\" font-weight=\"900\">y=x</text></svg>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Domain and range exchange roles","kind":"content","eyebrow":"The reverse model changes variable meanings","html":"<div class=\"v5-three\"><article><span>ORIGINAL</span><div>\\[D_f=[0,12],\\quad R_f=[6,24]\\]</div></article><article><span>INVERSE RELATION</span><div>\\[D_{f^{-1}}=[6,24],\\quad R_{f^{-1}}=[0,12]\\]</div></article><article><span>CONTEXT</span><p>The original predicts output from time; the inverse relation estimates time from output.</p></article></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"The horizontal-line test","kind":"content","eyebrow":"When is the inverse relation a function?","html":"<div class=\"v5-two\"><article><span>ONE-TO-ONE</span><p>Every horizontal line meets the graph at most once. Each output has one preimage, so the inverse relation is a function.</p></article><article><span>NOT ONE-TO-ONE</span><p>Some horizontal line meets the graph more than once. One inverse input would have multiple outputs.</p></article></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Restrict a domain to obtain an inverse function","kind":"content","eyebrow":"Choose one branch","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>The function \\(f(x)=x^2\\) on \\(\\mathbb R\\) is not one-to-one. Restrict the domain to \\(x\\ge0\\) and state the inverse function.</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>On \\(x\\ge0\\), the graph passes the horizontal-line test.</li><li>Write \\(y=x^2\\), swap variables: \\(x=y^2\\).</li><li>Because the restricted original output is non-negative, choose \\(y=\\sqrt{x}\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{f^{-1}(x)=\\sqrt{x},\\quad x\\ge0}\\]</div></section></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Inverse notation is not a reciprocal","kind":"content","eyebrow":"Two different operations","html":"<div class=\"v5-three\"><article><span>INVERSE FUNCTION</span><div>\\[f^{-1}(x)\\]</div><p>Reverses the input–output process.</p></article><article><span>RECIPROCAL</span><div>\\[\\frac1{f(x)}\\]</div><p>Divides 1 by the output.</p></article><article><span>CHECK</span><p>If \\(f(3)=11\\), then \\(f^{-1}(11)=3\\); this says nothing about \\(1/f(11)\\).</p></article></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Interpret an inverse value in context","kind":"content","eyebrow":"Reverse the question, not only the algebra","html":"<div class=\"v5-interpret\"><div>\\[T(8)=26\\]</div><p><b>Original:</b> an 8 km trip takes 26 minutes.</p><div>\\[T^{-1}(26)=8\\]</div><p><b>Inverse:</b> a 26-minute trip corresponds to a distance of 8 km, within the model.</p></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Fixed points lie on y=x","kind":"content","eyebrow":"A function and its inverse share these points","html":"<div class=\"v5-three\"><article><span>DEFINITION</span><div>\\[f(a)=a\\]</div><p>The input equals its output.</p></article><article><span>GRAPH</span><p>Fixed points are intersections of \\(y=f(x)\\) and \\(y=x\\).</p></article><article><span>EXAMPLE</span><div>\\[f(x)=2x-3\\Rightarrow x=3\\]</div></article></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Worked IB-style synthesis · cooling model","kind":"worked","eyebrow":"Function, graph, technology, and inverse meaning","html":"<div class=\"v5-worked\"><section class=\"v5-problem\"><span>PROBLEM</span><h2>A server-room temperature is modelled by \\(T(t)=18+12e^{-0.35t}\\) for \\(0\\le t\\le12\\), where \\(t\\) is minutes. Determine the range, find when the temperature first falls below 22°C, and interpret \\(T^{-1}(22)\\).</h2></section><section class=\"v5-solution\"><span>REASONING</span><ol><li>On the stated domain, the model decreases. Evaluate \\(T(0)=30\\) and \\(T(12)\\\\approx18.18\\), so the range is approximately \\([18.18,30]\\).</li><li>Solve \\(18+12e^{-0.35t}=22\\) using Intersect or logarithms: \\(t\\\\approx3.139\\).</li><li>Because the function is one-to-one on the domain, \\(T^{-1}(22)\\approx3.139\\).</li></ol><div class=\"v5-answer\">\\[\\boxed{R\\approx[18.18,30]\\ ^\\circ\\mathrm C,\\qquad t\\\\approx3.14\\text{ min}}\\]</div><div class=\"v5-check\"><b>Check</b><p>The inverse value means that a temperature of 22°C occurs about 3.14 minutes after cooling begins.</p></div></section></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Independent exit ticket","kind":"student","eyebrow":"One coherent response","html":"<div class=\"v5-student\"><div><span>YOUR TURN</span><h2>Create a contextual function with a stated domain. Give a table of three values, calculate one image, determine one preimage, state the range, identify one graph feature, and write one sentence interpreting an inverse-relation value.</h2></div><textarea class=\"student-note tall\" data-note=\"v5-exit\" placeholder=\"Show the mathematical evidence and interpretation.\"></textarea><details><summary>Reveal a model response</summary><div class=\"solution-panel\">A complete response must keep the same rule, variables, units, domain, table, graph features, and inverse interpretation consistent. Use the checklist in Mastery to self-assess.</div></details></div>","block":"F"},{"section":"2.1F · Inverse Relations","title":"Mastery and next step","kind":"content","eyebrow":"Evidence before familiarity","html":"<div class=\"v5-mastery\"><div><span>LEARN</span><b>88 screens</b><small>six teaching blocks</small></div><div><span>PRACTICE</span><b>96 questions</b><small>four balanced levels</small></div><div><span>QUIZ</span><b>18 questions</b><small>independent checkpoint</small></div><div><span>IB TASKS</span><b>6 tasks</b><small>Paper 1 and Paper 2 style</small></div></div><div class=\"v5-next\"><button class=\"primary-btn route-jump\" data-go=\"practice\">Practice Studio</button><button class=\"secondary-btn route-jump\" data-go=\"exam\">IB Tasks</button><button class=\"secondary-btn route-jump\" data-go=\"quiz\">Timed Quiz</button><button class=\"secondary-btn route-jump\" data-go=\"review\">Mastery</button><button class=\"secondary-btn\" type=\"button\" data-open-ti84>TI‑84 Practice Lab</button></div>","block":"F"}],"practice":[],"quiz":[],"exam":[],"review":{"title":"Functions mastery review","criteria":["I can justify whether a relation is a function from mappings, tables, equations, graphs, and contexts.","I can calculate images and determine every relevant preimage.","I can state mathematical and contextual domains and ranges using correct notation.","I can read and interpret graph features and reject non-contextual solutions.","I can use TI-84 workflows transparently and verify the result.","I can interpret inverse relations as coordinate exchange and reflection in y=x."],"transfer":"Before Lesson 2.2, explain how domain restrictions and graph features affect a linear or quadratic model."},"counts":{"slides":88,"practice":96,"quiz":18,"exam":6}};
